764	// Per-sample FULL (bidirectional) self-attention FORWARD over a tile. qkv is
765	// bf16 HBM [rows×3d] (q|k|v). Writes ctx fp32 HBM [rows×d] and attn weights fp32
766	// to `attn_w` [nSamp×H×S×S]. Each (sample,head,qpos) row owned by one thread —
767	// identical math to vit_attention, looped over samples. DELTA 1 vs decoder: NO
768	// causal mask — every key kj contributes for every query qi.
769	__device__ __forceinline__ void vittc_attn_fwd_tile(
770	        const __nv_bfloat16* __restrict__ qkv, int nrows,
771	        float* __restrict__ ctx, float* __restrict__ attn_w) {
772	    const int nsamp = nrows / vit::kSeq;
773	    const float scale = vit::attn_scale();
774	    const int rows_per = nsamp * vit::kHeads * vit::kSeq;   // (sample,head,qpos)
775	    for (int r = threadIdx.x; r < rows_per; r += blockDim.x) {
776	        const int si = r / (vit::kHeads * vit::kSeq);
777	        const int rem = r % (vit::kHeads * vit::kSeq);
778	        const int hh = rem / vit::kSeq, qi = rem % vit::kSeq;
779	        const int qoff = hh * vit::kDhead;
780	        const int rbase = si * vit::kSeq;        // first row of this sample
781	        const __nv_bfloat16* qrow = qkv + (int64_t)(rbase + qi) * 3 * vit::kD + qoff;
782	        float maxs = -CUDART_INF_F; float sc[vit::kSeq];
783	        #pragma unroll
784	        for (int kj = 0; kj < vit::kSeq; ++kj) {   // FULL: every key position
785	            const __nv_bfloat16* krow = qkv + (int64_t)(rbase + kj) * 3 * vit::kD + vit::kD + qoff;
786	            float dot = 0.0f;
787	            #pragma unroll
788	            for (int t = 0; t < vit::kDhead; ++t)
789	                dot += __bfloat162float(qrow[t]) * __bfloat162float(krow[t]);
790	            sc[kj] = dot * scale; maxs = fmaxf(maxs, sc[kj]);
791	        }
792	        float denom = 0.0f;
793	        #pragma unroll
794	        for (int kj = 0; kj < vit::kSeq; ++kj) { float e = __expf(sc[kj] - maxs); sc[kj] = e; denom += e; }
795	        float invd = 1.0f / denom;
796	        float* aw = attn_w + ((int64_t)(si * vit::kHeads + hh) * vit::kSeq + qi) * vit::kSeq;
797	        #pragma unroll
798	        for (int kj = 0; kj < vit::kSeq; ++kj) aw[kj] = sc[kj] * invd;
799	        #pragma unroll
800	        for (int t = 0; t < vit::kDhead; ++t) {
801	            float acc = 0.0f;
802	            #pragma unroll
803	            for (int kj = 0; kj < vit::kSeq; ++kj) {  // FULL: all kj
804	                float vv = __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * vit::kD + 2 * vit::kD + qoff + t]);
805	                acc += aw[kj] * vv;
806	            }
807	            ctx[(int64_t)(rbase + qi) * vit::kD + qoff + t] = acc;
808	        }
809	    }
810	    __syncthreads();
811	}
