813	// Global SAMPLE index of the si-th sample in a tile whose first token row is g0.
814	__device__ __forceinline__ int si_global(int g0, int si) { return g0 / vit::kSeq + si; }
815	
816	// ════════════════════════════════════════════════════════════════════════
817	//  FORWARD over one TOKEN TILE (nrows = nsamp samples × kSeq positions), global
818	//  token rows [g0, g0+nrows). Tile-batched: the four per-layer linears run on
819	//  wgmma (M=nrows, N-tiled); attention/LN/GELU scalar fp32; head/CE scalar
820	//  per-sample. Writes VitActs X-inputs (bf16 dW operands), the per-CTA tile
821	//  scratch, and returns the tile's summed NLL (thread 0 holds it).
822	//
823	//  DELTA 2 (patch_proj embedding): X_in[0][CLS row] = cls + pos[0];
824	//    X_in[0][patch row 1+i] = patch_proj(patch_i) + pos[1+i]. The patch_proj is
825	//    a wgmma fwd GEMM over the tile's patch rows (M = nsamp*16 = kPatchPerTile,
826	//    K=49 padded to 64). The float patches are staged into X_patch (bf16) first,
827	//    then patch_proj reads them.
828	//  `patches` is HBM float [B, 16, 49]; `tgt_ids` HBM int32 [B].
829	// ════════════════════════════════════════════════════════════════════════
830	__device__ float vittc_forward_tile(
831	        const VitWeights& w, int g0, int nrows, const VitActs& acts,
832	        const VitTileScratch& sc, const float* __restrict__ patches,
833	        const int* __restrict__ tgt_ids,
834	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
835	    const int nsamp = nrows / vit::kSeq;
836	#if SG_TUNED_VIT_P1_SUBTILE_S < 64
837	    // B1 sub-tile: nrows = kSeq·S is generally not a multiple of 64 → the linear
838	    // GEMMs issue ceil(nrows/64) m64 atoms and guard pad rows with m_real=nrows.
839	    const int m_atoms_rt = (nrows + wgs::kWgmmaAtomM - 1) / wgs::kWgmmaAtomM;
840	#endif
841	    const int npatch_rows = nsamp * vit::kNPatch;
842	    const int gp0 = (g0 / vit::kSeq) * vit::kNPatch;   // first PATCH row of this tile
843	    // ── Stage this tile's patches into X_patch (bf16) as patch token rows.
844	    //    Sample si's patch p is global patch row gp0 + si*kNPatch + p; the source
845	    //    is patches[(g0/kSeq + si)*kNPatch*kPatch + p*kPatch + c]. ──
846	    for (int idx = threadIdx.x; idx < npatch_rows * vit::kPatch; idx += blockDim.x) {
847	        const int pr = idx / vit::kPatch, c = idx % vit::kPatch;
848	        const int si = pr / vit::kNPatch, p = pr % vit::kNPatch;
849	        const int gs = si_global(g0, si);
850	        float v = patches[((int64_t)gs * vit::kNPatch + p) * vit::kPatch + c];
851	        acts.X_patch[(int64_t)(gp0 + pr) * vit::kPatch + c] = __float2bfloat16(v);
852	    }
853	    __syncthreads();
854	    // ── patch_proj: proj[pr, :] = X_patch[pr,:49] @ patch_w[d,49]ᵀ + patch_b.
855	    //    fp32 → sc.work (patch rows). K=49 padded to 64 (one m64 atom block per
856	    //    64 patch rows). M = npatch_rows (= nsamp*16) issued as ceil/64 atoms. ──
857	    {
858	        const int pm_atoms = (npatch_rows + wgs::kWgmmaAtomM - 1) / wgs::kWgmmaAtomM;
859	        const __nv_bfloat16* Xp = acts.X_patch + (int64_t)gp0 * vit::kPatch;
860	        // fwd into sc.work [npatch_rows, d] fp32 (Kpad=64, Kreal=49).
861	        const int Kpad = ((vit::kPatch + wgs::kWgmmaAtomK - 1) / wgs::kWgmmaAtomK) * wgs::kWgmmaAtomK; // 64
862	        const int N = SG_TUNED_TILE_N;
863	        const int k_steps = Kpad / wgs::kWgmmaAtomK;
864	        for (int n0 = 0; n0 < vit::kD; n0 += N) {
865	            const int n_real = (vit::kD - n0) < N ? (vit::kD - n0) : N;
866	            auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
867	                return k < vit::kPatch ? Xp[(int64_t)m * vit::kPatch + k] : __float2bfloat16(0.f); };
868	            auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
869	                int nn = n0 + n; return (nn < vit::kD && k < vit::kPatch) ? __float2bfloat16(w.patch_w[(int64_t)nn * vit::kPatch + k]) : __float2bfloat16(0.f); };
870	            auto out  = [&] (int m, int n, float v) { sc.work[(int64_t)m * vit::kD + n0 + n] = v; };
871	            tc_gemm_block_unpipelined<SG_TUNED_TILE_N, /*MaxAtomsM=*/kAtomsM>(
872	                0, pm_atoms, n_real, k_steps SG_VIT_PATCH_MREAL_ARG, srcA, srcB, out, sA, sB);
873	        }
874	    }
875	    __syncthreads();
876	    // ── Build X_in[0]: CLS rows (pos 0 of each sample) = cls + pos[0]; patch
877	    //    rows (pos 1+i) = proj(patch_i) + pos[1+i]. bf16. ──
878	    for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
879	        const int r = idx / vit::kD, j = idx % vit::kD;
880	        const int g = g0 + r;
881	        const int sp = g % vit::kSeq;            // position within the sample
882	        float v;
883	        if (sp == 0) {
884	            v = w.cls[j] + w.pos[j];             // CLS + pos[0]
885	        } else {
886	            const int si = r / vit::kSeq;
887	            const int p = sp - 1;                // patch index 0..15
888	            const int pr = si * vit::kNPatch + p;
889	            v = sc.work[(int64_t)pr * vit::kD + j] + w.pos[(int64_t)sp * vit::kD + j] + w.patch_b[j];
890	        }
891	        acts.X_in[0][(int64_t)g * vit::kD + j] = __float2bfloat16(v);
892	    }
893	    __syncthreads();
894	
895	    for (int li = 0; li < vit::kLayers; ++li) {
896	        const VitWeights::Layer& L = w.layer[li];
897	        const __nv_bfloat16* Xin = acts.X_in[li] + (int64_t)g0 * vit::kD;        // [nrows,d]
898	        // qkv = Xin @ in_w^T + in_b   (N=3d, K=d). bf16 → scratch.qkv[li].
899	        vittc_gemm_fwd<SG_TUNED_TILE_N>(Xin, L.in_w, sc.qkv[li], vit::kD, vit::kD, 3 * vit::kD, SG_VIT_P1_BF16_MA_MR, sA, sB);
900	        __syncthreads();
901	        // add in_b (the fwd GEMM did W only; biases folded in scalar here for qkv).
902	        for (int idx = threadIdx.x; idx < nrows * 3 * vit::kD; idx += blockDim.x) {
903	            const int j = idx % (3 * vit::kD);
904	            float v = __bfloat162float(sc.qkv[li][idx]) + L.in_b[j];
905	            sc.qkv[li][idx] = __float2bfloat16(v);
906	        }
907	        __syncthreads();
908	        // attention (FULL) → ctx (work fp32) + attn[li] weights.
909	        vittc_attn_fwd_tile(sc.qkv[li], nrows, sc.work, sc.attn[li]);
910	        // ctx bf16 → X_ctx[li] (out_proj input + its dW operand).
911	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
912	            const int r = idx / vit::kD, j = idx % vit::kD;
913	            acts.X_ctx[li][(int64_t)(g0 + r) * vit::kD + j] = __float2bfloat16(sc.work[(int64_t)r * vit::kD + j]);
914	        }
915	        __syncthreads();
916	        // a = X_ctx @ out_w^T (+ out_b). fp32 → work.
917	        vittc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_ctx[li] + (int64_t)g0 * vit::kD, L.out_w,
918	                                            sc.work, vit::kD, vit::kD SG_VIT_P1_F32_MA_MR, sA, sB);
919	        __syncthreads();
920	        // r1 = Xin + a + out_b → work (fp32).
921	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
922	            const int r = idx / vit::kD, j = idx % vit::kD;
923	            sc.work[(int64_t)r * vit::kD + j] += __bfloat162float(Xin[(int64_t)r * vit::kD + j]) + L.out_b[j];
924	        }
925	        __syncthreads();
926	        // n1(r1) → x1 (fp32) + caches[li]; then bf16 → X_x1[li].
927	        vittc_ln_fwd_tile(sc.work, L.n1_w, L.n1_b, nrows, sc.x1, sc.n1x[li], sc.n1i[li], red);
928	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
929	            const int r = idx / vit::kD, j = idx % vit::kD;
930	            acts.X_x1[li][(int64_t)(g0 + r) * vit::kD + j] = __float2bfloat16(sc.x1[(int64_t)r * vit::kD + j]);
931	        }
932	        __syncthreads();
933	        // ff0 = X_x1 @ ff0_w^T (+ ff0_b). fp32 → work; pre-gelu bf16 → ff0pre;
934	        // gelu(pre+b) → X_gact[li] (bf16).
935	        vittc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_x1[li] + (int64_t)g0 * vit::kD, L.ff0_w,
936	                                            sc.work, vit::kD, vit::kDff SG_VIT_P1_F32_MA_MR, sA, sB);
937	        __syncthreads();
938	        for (int idx = threadIdx.x; idx < nrows * vit::kDff; idx += blockDim.x) {
939	            const int r = idx / vit::kDff, j = idx % vit::kDff;
940	            float pre = sc.work[(int64_t)r * vit::kDff + j] + L.ff0_b[j];
941	            sc.ff0pre[li][(int64_t)r * vit::kDff + j] = __float2bfloat16(pre);
942	            acts.X_gact[li][(int64_t)(g0 + r) * vit::kDff + j] = __float2bfloat16(vit_gelu(pre));
943	        }
944	        __syncthreads();
945	        // ff2 = X_gact @ ff2_w^T (+ ff2_b). fp32 → work.
946	        vittc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_gact[li] + (int64_t)g0 * vit::kDff, L.ff2_w,
947	                                            sc.work, vit::kDff, vit::kD SG_VIT_P1_F32_MA_MR, sA, sB);
948	        __syncthreads();
949	        // r2 = x1 + ff2 + ff2_b → work (fp32).
950	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
951	            const int r = idx / vit::kD, j = idx % vit::kD;
952	            sc.work[(int64_t)r * vit::kD + j] += sc.x1[(int64_t)r * vit::kD + j] + L.ff2_b[j];
953	        }
954	        __syncthreads();
955	        if (li + 1 < vit::kLayers) {
956	            // n2(r2) → finalin (fp32 reused) + n2 caches[li]; bf16 → X_in[li+1].
957	            vittc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
958	            for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
959	                const int r = idx / vit::kD, j = idx % vit::kD;
960	                acts.X_in[li + 1][(int64_t)(g0 + r) * vit::kD + j] = __float2bfloat16(sc.finalin[(int64_t)r * vit::kD + j]);
961	            }
962	            __syncthreads();
963	        } else {
964	            // last layer: n2(r2) → finalin (fp32, all positions; head reads pos 0).
965	            vittc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
966	        }
967	    }
968	
969	    // ── Final norm + head + CE, scalar PER-SAMPLE on the CLS position (0) only.
970	    //    DELTA 3: CLS at pos 0 (row si*kSeq), not the last position. ──
971	    float nll_acc = 0.0f;
972	#ifdef SG_VIT_PROFILE
973	    __syncthreads(); unsigned long long _ha = (threadIdx.x == 0) ? clock64() : 0;
974	#endif
975	    for (int si = 0; si < nsamp; ++si) {
976	        const int rcls = si * vit::kSeq;                  // CLS row (pos 0)
977	        const float* hcls = sc.finalin + (int64_t)rcls * vit::kD;
978	        float sum = 0.0f;
979	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) sum += hcls[j];
980	        float mean = vit_block_sum(sum, red) / (float)vit::kD;
981	        float vs = 0.0f;
982	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) { float c = hcls[j] - mean; vs += c * c; }
983	        float var = vit_block_sum(vs, red) / (float)vit::kD;
984	        float iv = rsqrtf(var + vit::kLnEps);
985	        if (threadIdx.x == 0) sc.fni[rcls] = iv;
986	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
987	            float xh = (hcls[j] - mean) * iv;
988	            sc.fnx[(int64_t)rcls * vit::kD + j] = xh;
989	            float hn = xh * w.norm_w[j] + w.norm_b[j];
990	            acts.X_hn[(int64_t)si_global(g0, si) * vit::kD + j] = __float2bfloat16(hn);
991	        }
992	        __syncthreads();
993	        // logits[o] = hn · out_w[o] + out_b[o]  (scalar; hn read from X_hn bf16).
994	        float* lg = sc.logits + (int64_t)si * vit::kVocab;
995	        const __nv_bfloat16* hnb = acts.X_hn + (int64_t)si_global(g0, si) * vit::kD;
996	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
997	            const float* Wr = w.out_w + (int64_t)o * vit::kD;
998	            float acc = w.out_b[o];
999	            #pragma unroll 4
1000	            for (int k = 0; k < vit::kD; ++k) acc += __bfloat162float(hnb[k]) * Wr[k];
1001	            lg[o] = acc;
1002	        }
1003	        __syncthreads();
1004	        int tgt = tgt_ids[si_global(g0, si)];
1005	        float lmax = -CUDART_INF_F;
1006	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
1007	        lmax = vit_block_max(lmax, red);
1008	        float es = 0.0f;
1009	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
1010	        es = vit_block_sum(es, red);
1011	        float logz = lmax + __logf(es);
1012	        if (threadIdx.x == 0) nll_acc += (logz - lg[tgt]);
1013	        __syncthreads();
1014	    }
1015	#ifdef SG_VIT_PROFILE
1016	    __syncthreads();
1017	    if (threadIdx.x == 0) atomicMax(&g_vit_prof_head[0], clock64() - _ha);
1018	#endif
1019	    return nll_acc;
1020	}
