1022	// Attention BACKWARD over a tile (FULL — no causal triangle). Reads qkv (bf16),
1023	// attn weights, dctx [nrows,d] fp32; writes dqkv [nrows,3d] fp32 into `dqkv_out`.
1024	// dsc is the per-CTA dscores scratch. Mirror of vit_backward_sample's attention
1025	// (A: dv, B: dscores, C: dq/dk), looped over samples. scale = 1/sqrt(dh).
1026	__device__ __forceinline__ void vittc_attn_bwd_tile(
1027	        const __nv_bfloat16* __restrict__ qkv, const float* __restrict__ attn_w,
1028	        const float* __restrict__ dctx, int nrows,
1029	        float* __restrict__ dqkv_out, float* __restrict__ dsc) {
1030	    const int nsamp = nrows / vit::kSeq;
1031	    const float scale = vit::attn_scale();
1032	    // A: dv[kj] = Σ_{qi} attn[qi,kj] * dctx[qi].  Owner: (sample,kj,head,t). FULL.
1033	    for (int r = threadIdx.x; r < nsamp * vit::kSeq * vit::kHeads * vit::kDhead; r += blockDim.x) {
1034	        const int si  = r / (vit::kSeq * vit::kHeads * vit::kDhead);
1035	        int rem = r % (vit::kSeq * vit::kHeads * vit::kDhead);
1036	        const int kj  = rem / (vit::kHeads * vit::kDhead);
1037	        rem = rem % (vit::kHeads * vit::kDhead);
1038	        const int hh  = rem / vit::kDhead, t = rem % vit::kDhead;
1039	        const int qoff = hh * vit::kDhead;
1040	        const int rbase = si * vit::kSeq;
1041	        const float* aw = attn_w + ((int64_t)(si * vit::kHeads + hh) * vit::kSeq) * vit::kSeq;  // [S,S]
1042	        float acc = 0.0f;
1043	        #pragma unroll
1044	        for (int qi = 0; qi < vit::kSeq; ++qi)   // FULL: all qi
1045	            acc += aw[qi * vit::kSeq + kj] * dctx[(int64_t)(rbase + qi) * vit::kD + qoff + t];
1046	        dqkv_out[(int64_t)(rbase + kj) * 3 * vit::kD + 2 * vit::kD + qoff + t] = acc;   // dv block
1047	    }
1048	    __syncthreads();
1049	    // B: dscores ds[qi,kj] = attn*(datt - Σ_k datt*attn)*scale (FULL, all kj).
1050	    //    datt[kj] = Σ_t dctx[qi,qoff+t]*v[kj,qoff+t]. Owner: (sample,head,qi).
1051	    for (int r = threadIdx.x; r < nsamp * vit::kHeads * vit::kSeq; r += blockDim.x) {
1052	        const int si = r / (vit::kHeads * vit::kSeq);
1053	        int rem = r % (vit::kHeads * vit::kSeq);
1054	        const int hh = rem / vit::kSeq, qi = rem % vit::kSeq;
1055	        const int qoff = hh * vit::kDhead;
1056	        const int rbase = si * vit::kSeq;
1057	        const float* aw = attn_w + ((int64_t)(si * vit::kHeads + hh) * vit::kSeq) * vit::kSeq;
1058	        float datt[vit::kSeq];
1059	        #pragma unroll
1060	        for (int kj = 0; kj < vit::kSeq; ++kj) {
1061	            float acc = 0.0f;
1062	            #pragma unroll
1063	            for (int t = 0; t < vit::kDhead; ++t)
1064	                acc += dctx[(int64_t)(rbase + qi) * vit::kD + qoff + t]
1065	                     * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * vit::kD + 2 * vit::kD + qoff + t]);
1066	            datt[kj] = acc;
1067	        }
1068	        float dot = 0.0f;
1069	        #pragma unroll
1070	        for (int kj = 0; kj < vit::kSeq; ++kj) dot += datt[kj] * aw[qi * vit::kSeq + kj];
1071	        float* ds = dsc + ((int64_t)(si * vit::kHeads + hh) * vit::kSeq + qi) * vit::kSeq;
1072	        #pragma unroll
1073	        for (int kj = 0; kj < vit::kSeq; ++kj) {
1074	            float a = aw[qi * vit::kSeq + kj];
1075	            ds[kj] = a * (datt[kj] - dot) * scale;
1076	        }
1077	    }
1078	    __syncthreads();
1079	    // C: dq[qi]=Σ_kj ds[qi,kj]*k[kj]; dk[kj]=Σ_qi ds[qi,kj]*q[qi]. FULL. Owner: (sample,pos,head,t).
1080	    for (int r = threadIdx.x; r < nsamp * vit::kSeq * vit::kHeads * vit::kDhead; r += blockDim.x) {
1081	        const int si = r / (vit::kSeq * vit::kHeads * vit::kDhead);
1082	        int rem = r % (vit::kSeq * vit::kHeads * vit::kDhead);
1083	        const int pos = rem / (vit::kHeads * vit::kDhead);
1084	        rem = rem % (vit::kHeads * vit::kDhead);
1085	        const int hh = rem / vit::kDhead, t = rem % vit::kDhead;
1086	        const int qoff = hh * vit::kDhead;
1087	        const int rbase = si * vit::kSeq;
1088	        const float* ds = dsc + ((int64_t)(si * vit::kHeads + hh) * vit::kSeq) * vit::kSeq;  // [S,S]
1089	        float dq = 0.0f, dk = 0.0f;
1090	        #pragma unroll
1091	        for (int kj = 0; kj < vit::kSeq; ++kj) {
1092	            dq += ds[pos * vit::kSeq + kj] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * vit::kD + vit::kD + qoff + t]);
1093	            dk += ds[kj * vit::kSeq + pos] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * vit::kD + qoff + t]);
1094	        }
1095	        dqkv_out[(int64_t)(rbase + pos) * 3 * vit::kD + qoff + t] = dq;             // dq block
1096	        dqkv_out[(int64_t)(rbase + pos) * 3 * vit::kD + vit::kD + qoff + t] = dk;   // dk block
1097	    }
1098	    __syncthreads();
1099	}
1100	
1101	// ════════════════════════════════════════════════════════════════════════
1102	//  BACKWARD over one TOKEN TILE. Assumes vittc_forward_tile ran for THIS tile.
1103	//  Fork B: computes dX via wgmma and WRITES the dY output-adjoints to VitActs
1104	//  (dY_qkv/dY_a/dY_ff0/dY_ff2/dY_logits) + dh0 for P2's dW — it does NOT touch
1105	//  the weight dW here. ACCUMULATES the 10 LN-vector grads into `lnvec`
1106	//  [kNumLnVec × d] (deterministic single-owner-per-j). `B` is the full batch
1107	//  (CE mean scale). DELTA 3: head/final-norm bwd on the CLS row (pos 0).
1108	// ════════════════════════════════════════════════════════════════════════
1109	__device__ void vittc_backward_tile(
1110	        const VitWeights& w, int g0, int nrows, int B, const VitActs& acts,
1111	        const VitTileScratch& sc, const int* __restrict__ tgt_ids,
1112	        float* __restrict__ lnvec, float* __restrict__ work2,
1113	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
1114	    const int nsamp = nrows / vit::kSeq;
1115	#if SG_TUNED_VIT_P1_SUBTILE_S < 64
1116	    // B1 sub-tile: dX GEMMs issue ceil(nrows/64) m64 atoms with m_real=nrows.
1117	    const int m_atoms_rt = (nrows + wgs::kWgmmaAtomM - 1) / wgs::kWgmmaAtomM;
1118	#endif
1119	    float* gn_n1w[vit::kLayers]; float* gn_n1b[vit::kLayers];
1120	    float* gn_n2w[vit::kLayers]; float* gn_n2b[vit::kLayers];
1121	    for (int li = 0; li < vit::kLayers; ++li) {
1122	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * vit::kD;
1123	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * vit::kD;
1124	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * vit::kD;
1125	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * vit::kD;
1126	    }
1127	    float* gn_normw = lnvec + (int64_t)8 * vit::kD;
1128	    float* gn_normb = lnvec + (int64_t)9 * vit::kD;
1129	
1130	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B → dY_logits (bf16);
1131	    //    head dX → dhn; final-norm bwd → dh on the CLS row (pos 0), zero others. ──
1132	    for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
1133	    __syncthreads();
1134	#ifdef SG_VIT_PROFILE
1135	    unsigned long long _hb = (threadIdx.x == 0) ? clock64() : 0;
1136	#endif
1137	    for (int si = 0; si < nsamp; ++si) {
1138	        const int rcls = si * vit::kSeq;          // CLS row (pos 0)
1139	        const int gs = si_global(g0, si);
1140	        float* lg = sc.logits + (int64_t)si * vit::kVocab;
1141	        int tgt = tgt_ids[gs];
1142	        float lmax = -CUDART_INF_F;
1143	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
1144	        lmax = vit_block_max(lmax, red);
1145	        float es = 0.0f;
1146	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
1147	        es = vit_block_sum(es, red);
1148	        float inv_es = 1.0f / es;
1149	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
1150	            float smo = __expf(lg[o] - lmax) * inv_es;
1151	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
1152	            lg[o] = dl;
1153	            acts.dY_logits[(int64_t)gs * vit::kVocab + o] = __float2bfloat16(dl);
1154	        }
1155	        __syncthreads();
1156	        // dhn[j] = Σ_o dlogits[o] * out_w[o,j] → stash into work row rcls.
1157	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1158	            float dhn = 0.0f;
1159	            for (int o = 0; o < vit::kVocab; ++o)
1160	                dhn += lg[o] * w.out_w[(int64_t)o * vit::kD + j];
1161	            sc.work[(int64_t)rcls * vit::kD + j] = dhn;
1162	        }
1163	        __syncthreads();
1164	        // norm γ/β: dnorm_w[j] += dhn*xhat; dnorm_b[j] += dhn. (Only CLS row.)
1165	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1166	            float dhn = sc.work[(int64_t)rcls * vit::kD + j];
1167	            float xh = sc.fnx[(int64_t)rcls * vit::kD + j];
1168	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
1169	        }
1170	        __syncthreads();
1171	        // LN dx (single CLS row): dxhat=dhn*norm_w; reduce; dh[rcls] = inv*(...).
1172	        {
1173	            const float* dyr = sc.work + (int64_t)rcls * vit::kD;
1174	            const float* xhr = sc.fnx + (int64_t)rcls * vit::kD;
1175	            float sda = 0.0f, sdax = 0.0f;
1176	            for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1177	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
1178	            }
1179	            sda = vit_block_sum(sda, red); sdax = vit_block_sum(sdax, red);
1180	            float iv = sc.fni[rcls];
1181	            for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1182	                float dxhat = dyr[j] * w.norm_w[j];
1183	                sc.dh[(int64_t)rcls * vit::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)vit::kD);
1184	            }
1185	            __syncthreads();
1186	        }
1187	    }
1188	#ifdef SG_VIT_PROFILE
1189	    __syncthreads();
1190	    if (threadIdx.x == 0) atomicMax(&g_vit_prof_head[1], clock64() - _hb);
1191	#endif
1192	    // scratch.dh now = grad wrt last-layer output [nrows,d] (only CLS positions nonzero).
1193	
1194	    for (int li = vit::kLayers - 1; li >= 0; --li) {
1195	        const VitWeights::Layer& L = w.layer[li];
1196	        // n2 bwd: dh → dr2 (work fp32), accumulate n2 γ/β. xhat=n2x[li], inv=n2i[li].
1197	        vittc_ln_bwd_tile(sc.dh, sc.n2x[li], sc.n2i[li], L.n2_w, nrows, sc.work, gn_n2w[li], gn_n2b[li], red);
1198	        // r2 = x1 + ff2 → dx1 = dr2 (residual), dff2 = dr2. dff2 → dY_ff2 (bf16).
1199	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
1200	            work2[idx] = sc.work[idx];   // dx1 := dr2 (residual part)
1201	            acts.dY_ff2[li][(int64_t)g0 * vit::kD + idx] = __float2bfloat16(sc.work[idx]);  // dff2
1202	        }
1203	        __syncthreads();
1204	        // ff2 dX: dgact = dff2 @ ff2_w  (N=dff, K=d). fp32 → sc.work (dr2 no longer needed).
1205	        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff2[li] + (int64_t)g0 * vit::kD, L.ff2_w,
1206	                                           sc.work, vit::kDff, vit::kD SG_VIT_P1_F32_MA_MR, sA, sB);  // dgact [nrows,dff]
1207	        __syncthreads();
1208	        // dff0 = dgact * gelu'(ff0pre) → dY_ff0 (bf16) AND keep fp32 in sc.work for dX.
1209	        for (int idx = threadIdx.x; idx < nrows * vit::kDff; idx += blockDim.x) {
1210	            float dff0 = sc.work[idx] * vit_gelu_grad(__bfloat162float(sc.ff0pre[li][idx]));
1211	            sc.work[idx] = dff0;
1212	            acts.dY_ff0[li][(int64_t)g0 * vit::kDff + idx] = __float2bfloat16(dff0);
1213	        }
1214	        __syncthreads();
1215	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32 → sc.x1.
1216	        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * vit::kDff, L.ff0_w,
1217	                                           sc.x1, /*Kin=*/vit::kD, /*Nout=*/vit::kDff SG_VIT_P1_F32_MA_MR, sA, sB);  // dx1_ffn [nrows,d]
1218	        __syncthreads();
1219	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x)
1220	            work2[idx] += sc.x1[idx];   // dx1 = residual + FFN path
1221	        __syncthreads();
1222	        // n1 bwd: dx1 (work2) → dr1 (work), accumulate n1 γ/β.
1223	        vittc_ln_bwd_tile(work2, sc.n1x[li], sc.n1i[li], L.n1_w, nrows, sc.work, gn_n1w[li], gn_n1b[li], red);
1224	        // r1 = x_in + a → da = dr1 (out_proj output adjoint), dx_in = dr1 (residual).
1225	        // SAVE residual dr1 into sc.dh (free); da → dY_a (bf16).
1226	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
1227	            sc.dh[idx] = sc.work[idx];   // residual dx_in := dr1 (saved across attn bwd)
1228	            acts.dY_a[li][(int64_t)g0 * vit::kD + idx] = __float2bfloat16(sc.work[idx]);  // da
1229	        }
1230	        __syncthreads();
1231	        // out_proj dX: dctx = da @ out_w  (N=d, K=d). fp32 → sc.work (dctx [nrows,d]).
1232	        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * vit::kD, L.out_w,
1233	                                           sc.work, vit::kD, vit::kD SG_VIT_P1_F32_MA_MR, sA, sB);  // dctx
1234	        __syncthreads();
1235	        // attention bwd (FULL): (qkv[li], attn[li], dctx=work) → dqkv [nrows,3d]
1236	        //   fp32 into work2 (3d=384 ≤ dff=512, fits). Then → dY_qkv (bf16).
1237	        vittc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
1238	        for (int idx = threadIdx.x; idx < nrows * 3 * vit::kD; idx += blockDim.x)
1239	            acts.dY_qkv[li][(int64_t)g0 * 3 * vit::kD + idx] = __float2bfloat16(work2[idx]);
1240	        __syncthreads();
1241	        // in_proj dX: dx_in_attn = dqkv @ in_w (output width Kin=d, contract Nout=3d).
1242	        //   fp32 → sc.work; ADD residual (in sc.dh) → new running adjoint dh.
1243	        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_qkv[li] + (int64_t)g0 * 3 * vit::kD, L.in_w,
1244	                                           sc.work, /*Kin=*/vit::kD, /*Nout=*/3 * vit::kD SG_VIT_P1_F32_MA_MR, sA, sB);  // dx_in_attn
1245	        __syncthreads();
1246	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x)
1247	            sc.dh[idx] += sc.work[idx];   // dx_in = residual (in dh) + attn path
1248	        __syncthreads();
1249	    }
1250	
1251	    // ── embedding bwd: dh = grad wrt h0 [nrows,d]. Write dh0 (bf16); the
1252	    //    cls/patch/pos owners (P2) read dh0 by global token row. ──
1253	    for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x)
1254	        acts.dh0[(int64_t)g0 * vit::kD + idx] = __float2bfloat16(sc.dh[idx]);
1255	    __syncthreads();
1256	}
1257	
1258	// ════════════════════════════════════════════════════════════════════════
1259	//  P2 — OUTPUT-STATIONARY dW. Each of the 10 weight matrices (patch_proj +
1260	//  in/out/ff0/ff2 ×L + head) dW = dYᵀ @ X is split into 64×N output tiles;
1261	//  tile_id % nCTA owns each. The owner CTA contracts the FULL token dim itself
1262	//  (ascending-t, no float atomics, no partials) via the validated dW
1263	//  orientation. Writes the tile into `grad`.
1264	//
1265	//  patch_proj dW = dh0_patch^T @ X_patch (K = Tp = nsamp·16; the patch rows of
1266	//  dh0, gathered against the patch token rows). The 9 transformer dW use K=T (B
1267	//  for the head). To unify, each spec carries an `X_is_patch` flag: when set,
1268	//  the dW contracts over the Tp PATCH rows, reading the dY adjoint from dh0's
1269	//  patch rows (via a global→patch-row map) and X from X_patch.
1270	// ════════════════════════════════════════════════════════════════════════
1271	struct VitDwSpec {
1272	    const __nv_bfloat16* dY;   // [K, Nout]  (for patch_proj: nullptr — uses dh0)
1273	    const __nv_bfloat16* X;    // [K, Kin]
1274	    int Nout; int Kin; int K;  // Kin = REAL in-dim; K = contraction length
1275	    int Kpad;                  // Kin padded to a multiple of 16 (=64 for patch_proj's Kin=49)... see note
1276	    int grad_off;              // element offset of this weight in `grad`
1277	    int bias_off;              // element offset of the bias in `grad`
1278	    int kind;                  // 0=transformer (dY/X both token rows), 1=patch_proj
1279	};
1280	
1281	// Build the 10 specs (called by all CTAs; cheap). T = B*kSeq; Tp = B*kNPatch.
1282	__device__ __forceinline__ void vittc_build_dw_specs(
1283	        const VitActs& acts, int B, int T, int Tp, VitDwSpec spec[10]) {
1284	    // vit_layout weight tensor indices (and bias idx). Per-layer block base = 4 + li*12:
1285	    //   in_w = base+0 (in_b base+1), out_w base+2 (out_b base+3),
1286	    //   ff0_w base+8 (ff0_b base+9), ff2_w base+10 (ff2_b base+11).
1287	    //   patch_proj.weight=1 (bias=2); head out.weight=30 (out.bias=31).
1288	    // spec[0] = patch_proj; spec[1..8] = transformer (li,kind); spec[9] = head.
1289	    {
1290	        VitDwSpec& sp = spec[0];
1291	        sp.dY = nullptr; sp.X = acts.X_patch; sp.Nout = vit::kD; sp.Kin = vit::kPatch;
1292	        sp.K = Tp; sp.Kpad = vit::kPatch;  // K (contraction over patch rows) IS Tp; Kin padding handled in run_tile
1293	        sp.grad_off = kVitOffsets[1]; sp.bias_off = kVitOffsets[2]; sp.kind = 1;
1294	    }
1295	    for (int s = 0; s < 8; ++s) {
1296	        const int li = s / 4, kk = s % 4;
1297	        const int base = 4 + li * 12;
1298	        VitDwSpec& sp = spec[1 + s];
1299	        sp.K = T; sp.kind = 0; sp.Kpad = 0;
1300	        if (kk == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * vit::kD; sp.Kin = vit::kD;   sp.grad_off = kVitOffsets[base + 0]; sp.bias_off = kVitOffsets[base + 1]; }
1301	        else if (kk == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = vit::kD;     sp.Kin = vit::kD;   sp.grad_off = kVitOffsets[base + 2]; sp.bias_off = kVitOffsets[base + 3]; }
1302	        else if (kk == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = vit::kDff;   sp.Kin = vit::kD;   sp.grad_off = kVitOffsets[base + 8]; sp.bias_off = kVitOffsets[base + 9]; }
1303	        else              { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = vit::kD;     sp.Kin = vit::kDff; sp.grad_off = kVitOffsets[base + 10]; sp.bias_off = kVitOffsets[base + 11]; }
1304	    }
1305	    VitDwSpec& hd = spec[9];
1306	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = vit::kVocab; hd.Kin = vit::kD; hd.K = B; hd.kind = 0; hd.Kpad = 0;
1307	    hd.grad_off = kVitOffsets[30]; hd.bias_off = kVitOffsets[31];
1308	}
1309	
1310	// Total number of 64×N dW output tiles across the 10 weights (for the tile loop).
1311	// ── dW M-atom INTERLEAVE group width (task #24 H3 port). A dW output "tile"
1312	//    (work item) owns a GROUP of up to kVitDwIL consecutive m64 atoms instead of
1313	//    one, so the engine runs kVitDwIL wgmmas/k-step into independent fragments
1314	//    sharing ONE staged X (B-operand) tile → the H1 win (overlap the MMAs +
1315	//    kVitDwIL× less X-operand HBM traffic) now applies to the dW K=T contraction.
1316	//    kVitDwIL == the engine's interleave cap kVitMaxIL so the ring smem
1317	//    (VitTcSmem.sA, sized kVitAtomsPerSlot=kVitMaxIL A-tiles/slot) and the
1318	//    selftest-validated dW path (gemm_dw_kernel: MaxAtomsM=8, kIL=2) match exactly.
1319	//    Ascending-k per atom is unchanged → numerics bit-identical + A/A/A
1320	//    determinism. ViT dW atom counts: patch_proj(d=128→2), qkv(3d=384→6),
1321	//    attn_out(d=128→2), ff0(dff=512→8), ff2(d=128→2), head(V=97→2) — all EVEN, but
1322	//    the ragged-tail logic (g_atoms = min) is kept for safety (no even shortcut). ──
1323	constexpr int kVitDwIL = kVitMaxIL;
1324	__device__ __host__ __forceinline__ int vit_dw_atoms(int Nout)  { return (Nout + 63) / 64; }
1325	__device__ __host__ __forceinline__ int vit_dw_groups(int Nout) {
1326	    return (vit_dw_atoms(Nout) + kVitDwIL - 1) / kVitDwIL;
1327	}
1328	
1329	// Total number of dW output WORK ITEMS (M-atom groups × N-tiles) across the 10
1330	// weights. The N-tiling is over Kin (the in-dim), padded so the GEMM N covers it.
1331	template <int N>
1332	__device__ __forceinline__ int vittc_dw_total_tiles(const VitDwSpec spec[10]) {
1333	    int n = 0;
1334	    for (int s = 0; s < 10; ++s)
1335	        n += vit_dw_groups(spec[s].Nout) * ((spec[s].Kin + N - 1) / N);
1336	    return n;
1337	}
1338	
1339	// Run ONE global dW WORK ITEM `gt` (if it belongs to this CTA): decode (weight,
1340	// M-atom GROUP, N-tile), then contract K via the dW GEMM into grad. The group is
1341	// up to kVitDwIL stacked m64 atoms → the engine interleaves them (kIL=kVitDwIL):
1342	// kVitDwIL wgmmas/k-step into independent fragments sharing ONE staged X B-tile
1343	// (H1's win, now on the dW K contraction). For patch_proj (kind==1) the dY adjoint
1344	// is dh0's PATCH rows: dh0 is [T,d] token-row-major; its patch rows for sample si,
1345	// patch p are at token row si*kSeq + (1+p). The dW contracts over the Tp patch rows
1346	// in ascending patch order (k=0..Tp-1 maps to si=k/kNPatch, p=k%kNPatch → token row
1347	// si*kSeq+1+p). The engine adds mbase0=mbase and passes the GLOBAL row m to the
1348	// accessors/out; the out lambda writes grad by global m (m<Nout guard handles a
1349	// ragged final group), so multi-atom groups need no per-atom shimming here.
1350	template <int N>
1351	__device__ __forceinline__ void vittc_dw_run_tile(
1352	        const VitDwSpec spec[10], int gt, const __nv_bfloat16* __restrict__ dh0,
1353	        float* __restrict__ grad, __nv_bfloat16* sA, __nv_bfloat16* sB) {
1354	    int acc = 0, s = 0, m_group = 0, n_tile = 0;
1355	    for (s = 0; s < 10; ++s) {
1356	        const int ng = vit_dw_groups(spec[s].Nout);
1357	        const int nt = (spec[s].Kin + N - 1) / N;
1358	        if (gt < acc + ng * nt) { int loc = gt - acc; m_group = loc / nt; n_tile = loc % nt; break; }
1359	        acc += ng * nt;
1360	    }
1361	    const VitDwSpec& sp = spec[s];
1362	    const int n_atoms = vit_dw_atoms(sp.Nout);
1363	    const int a0 = m_group * kVitDwIL;               // first atom of the group
1364	    const int g_atoms = (n_atoms - a0) < kVitDwIL ? (n_atoms - a0) : kVitDwIL;
1365	    const int mbase = a0 * 64;
1366	    const int n0 = n_tile * N;
1367	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1368	    const int Nout = sp.Nout, Kin = sp.Kin;
1369	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1370	    if (sp.kind == 1) {
1371	        // patch_proj: K = Tp patch rows (ascending), padded UP to a multiple of 16.
1372	        const int Tp = sp.K;
1373	        const int Kpad = ((Tp + wgs::kWgmmaAtomK - 1) / wgs::kWgmmaAtomK) * wgs::kWgmmaAtomK;
1374	        const int k_steps = Kpad / wgs::kWgmmaAtomK;
1375	        // A[m=out, k=patchrow] = dh0[token row of patchrow, out]  (transposed read).
1376	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1377	            if (m >= Nout || k >= Tp) return __float2bfloat16(0.f);
1378	            const int si = k / vit::kNPatch, p = k % vit::kNPatch;
1379	            const int trow = si * vit::kSeq + (1 + p);
1380	            return dh0[(int64_t)trow * vit::kD + m]; };
1381	        // B[n=in, k=patchrow] = X_patch[patchrow, in].
1382	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1383	            int nn = n0 + n; if (nn >= Kin || k >= Tp) return __float2bfloat16(0.f);
1384	            return X[(int64_t)k * Kin + nn]; };
1385	        auto out  = [&] (int m, int n, float v) {
1386	            if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1387	        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kVitDwIL>(
1388	            mbase, g_atoms, n_real, k_steps SG_VIT_DW_MREAL_ARG, srcA, srcB, out, sA, sB);
1389	        return;
1390	    }
1391	    const int k_steps = sp.K / wgs::kWgmmaAtomK;     // K = T or B (must be /16; padded by caller)
1392	    // A[m=out, k=t] = dY[t,out]  (transposed read); B[n=in, k=t] = X[t,in] (transposed).
1393	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1394	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
1395	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1396	        int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
1397	    auto out  = [&] (int m, int n, float v) {
1398	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1399	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kVitDwIL>(
1400	        mbase, g_atoms, n_real, k_steps SG_VIT_DW_MREAL_ARG, srcA, srcB, out, sA, sB);
1401	}
