1578	// Biases db. For the 8 transformer linears + head: db = Σ_K dY (per output row).
1579	// For patch_proj.bias: db[o] = Σ_{patch rows} dh0[token row, o]. Single owner per
1580	// output element → no atomics.
1581	// PERF FIX (structural, parity-preserved — gated by the K-scaled grad tol, which is
1582	// designed for fp32 accumulation-order differences at large K):
1583	//   (1) The ORIGINAL ran the FULL Σ_K (K up to T=278528) for EVERY bias element on
1584	//       EVERY CTA (no cta/nCTA guard) — 132× redundant work, the dominant cost of P2
1585	//       grad-assembly (measured 59.5% of the step). Columns are now PARTITIONED across
1586	//       CTAs (each global bias column owned by one CTA), removing the 132× redundancy.
1587	//   (2) The K-reduction per column was SERIAL on ONE thread (≈278528 iters). It is now
1588	//       WARP-PARALLEL: a WARP (32 lanes) co-reduces one column — each lane sums a
1589	//       strided 1/32 slice of K (ascending within the lane), then a shuffle tree sums
1590	//       the 32 lane-partials. 32× parallelism per column. The lane reads dY[k*Nout+o]
1591	//       at fixed o with k = lane, lane+32, … (stride 32·Nout); writes by lane 0 only.
1592	__device__ __forceinline__ void vittc_dw_biases(
1593	        const VitDwSpec spec[10], const __nv_bfloat16* __restrict__ dh0,
1594	        float* __restrict__ grad, int cta, int nCTA) {
1595	    const int warp = threadIdx.x >> 5;            // 0..(blockDim/32 - 1)
1596	    const int lane = threadIdx.x & 31;
1597	    const int nwarps = blockDim.x >> 5;
1598	    int gcol_base = 0;
1599	    for (int s = 0; s < 10; ++s) {
1600	        const VitDwSpec& sp = spec[s];
1601	        const int Nout = sp.Nout;
1602	        const bool patch = (sp.kind == 1);
1603	        const int K = sp.K;
1604	        // Each warp owns columns o = (its rank among this CTA's warps), strided. A
1605	        // global column gcol is owned by CTA (gcol % nCTA); within the CTA the warps
1606	        // round-robin the owned columns.
1607	        for (int o = 0; o < Nout; ++o) {
1608	            const int gcol = gcol_base + o;
1609	            if ((gcol % nCTA) != cta) continue;       // not this CTA's column
1610	            // round-robin owned columns across warps: count owned-so-far for THIS s.
1611	            // Cheap: derive the warp owner from the o-th owned index. We instead let
1612	            // every warp test (owned_index % nwarps == warp); compute owned_index by
1613	            // a strided scan-free rule: owned columns appear every nCTA in gcol, so
1614	            // the k-th owned column of this CTA has o such that (gcol_base+o)%nCTA==cta.
1615	            // Assign by (o / 1) round-robin is fine since the inner reduce dominates:
1616	            // use (o-th column's position) — approximate with o itself for balance.
1617	            if (((o) % nwarps) != warp) continue;     // warp owns this column
1618	            float part = 0.0f;
1619	            if (patch) {
1620	                for (int k = lane; k < K; k += 32) {
1621	                    const int si = k / vit::kNPatch, p = k % vit::kNPatch;
1622	                    const int trow = si * vit::kSeq + (1 + p);
1623	                    part += __bfloat162float(dh0[(int64_t)trow * vit::kD + o]);
1624	                }
1625	            } else {
1626	                const __nv_bfloat16* dY = sp.dY;
1627	                for (int k = lane; k < K; k += 32)
1628	                    part += __bfloat162float(dY[(int64_t)k * Nout + o]);
1629	            }
1630	            // Warp-reduce the 32 lane-partials (shuffle tree).
1631	            #pragma unroll
1632	            for (int off = 16; off > 0; off >>= 1)
1633	                part += __shfl_down_sync(0xffffffffu, part, off);
1634	            if (lane == 0) grad[sp.bias_off + o] = part;
1635	        }
1636	        gcol_base += Nout;
1637	    }
1638	}
